import { Pencil, Plus, Trash2 } from "lucide-react";
import { useState } from "react";
import { eventDate, eventRequest } from "../../services/eventApi";
import "./EventNotes.css";
const blank={eventId:"",noteTitle:"",noteDescription:"",priority:"medium",status:"open"};
export default function EventNotes({notes,events,reload}){const [form,setForm]=useState(blank),[edit,setEdit]=useState("");const save=async e=>{e.preventDefault();try{await eventRequest(`/vendor/events/notes${edit?`/${edit}`:""}`,{method:edit?"PUT":"POST",body:form});setForm(blank);setEdit("");reload()}catch(err){alert(err.response?.data?.message||err.message)}};const start=n=>{setEdit(n.id);setForm({eventId:n.event_id||"",noteTitle:n.note_title,noteDescription:n.note_description,priority:n.priority,status:n.status})};const remove=async id=>{if(!window.confirm("Delete this note?"))return;await eventRequest(`/vendor/events/notes/${id}`,{method:"DELETE"});reload()};return <section><header className="en-title"><small>EVENT WORKSPACE</small><h1>Event Notes</h1><p>Save operational reminders and track tasks with your events.</p></header><section className="en-layout"><form className="ed-panel en-form" onSubmit={save}><header><h3>{edit?"Edit note":"Add a note"}</h3><Plus size={18}/></header><label><span>Event (optional)</span><select value={form.eventId} onChange={e=>setForm({...form,eventId:e.target.value})}><option value="">General note</option>{events.map(e=><option value={e.id} key={e.id}>{e.event_name}</option>)}</select></label><label><span>Note title</span><input required value={form.noteTitle} onChange={e=>setForm({...form,noteTitle:e.target.value})}/></label><label><span>Description</span><textarea required rows="5" value={form.noteDescription} onChange={e=>setForm({...form,noteDescription:e.target.value})}/></label><div><label><span>Priority</span><select value={form.priority} onChange={e=>setForm({...form,priority:e.target.value})}><option>low</option><option>medium</option><option>high</option></select></label><label><span>Status</span><select value={form.status} onChange={e=>setForm({...form,status:e.target.value})}><option>open</option><option>in_progress</option><option>completed</option></select></label></div><button type="submit">{edit?"Update Note":"Save Note"}</button>{edit&&<button type="button" className="secondary" onClick={()=>{setEdit("");setForm(blank)}}>Cancel edit</button>}</form><div className="en-list">{notes.map(n=><article className={`ed-panel ${n.priority}`} key={n.id}><header><div><span>{n.priority} priority</span><h3>{n.note_title}</h3></div><div><button onClick={()=>start(n)}><Pencil size={15}/></button><button onClick={()=>remove(n.id)}><Trash2 size={15}/></button></div></header><p>{n.note_description}</p><footer><b>{n.event_name||"General"}</b><span className={`ed-status ${n.status==="completed"?"active":"pending"}`}>{n.status.replace("_"," ")}</span><small>{eventDate(n.updated_at)}</small></footer></article>)}{!notes.length&&<article className="ed-panel ed-empty">No notes yet. Add your first reminder.</article>}</div></section></section>}
